class Solution {
public:
    long long maximumSum(vector<int>& nums, int m, int l, int r) {
        int n=nums.size();
        const long long NEG=-(1LL<<60);
        vector<long long> pre(n+1,0);
        for(int i=0;i<n;++i) pre[i+1]=pre[i]+nums[i];
        vector<long long> prev(n+1,0),cur(n+1,NEG);
        long long answer=NEG;
        for(int t=1;t<=m;++t) {
            deque<int> dq;
            fill(cur.begin(),cur.end(),NEG);
            for(int i=1;i<=n;++i) {
                int add=i-l;
                if(add>=0 && prev[add]!=NEG) {
                    while(!dq.empty() && prev[dq.back()]-pre[dq.back()]<=prev[add]-pre[add]) dq.pop_back();
                    dq.push_back(add);
                }
                while(!dq.empty() && dq.front()<i-r) dq.pop_front();
                cur[i]=cur[i-1];
                if(!dq.empty()) cur[i]=max(cur[i],pre[i]+prev[dq.front()]-pre[dq.front()]);
            }
            answer=max(answer,cur[n]);
            prev.swap(cur);
        }
        return answer;
    }
};
